files.content:
:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d45;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-hover: #ffe08a;
  --accent-pressed: #e6b85c;
  --disabled: #5a5d7a;
  --border: #3e4160;
  --focus-ring: #ffcd75;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  line-height: 1.5;
  font-size: 18px;
}

.quiz-container {
  width: 100%;
  max-width: 480px;
}

.card {
  background: var(--card-bg);
  border: 3px solid var(--border);
  border-radius: 4px;
  padding: 2rem 1.5rem;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.score-display {
  font-size: 1.125rem;
  text-align: right;
  color: var(--accent);
  font-weight: 600;
}

.question {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  padding: 1rem 0;
  letter-spacing: 0.02em;
}

.answers {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.answer-btn,
.control-btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 600;
  padding: 1rem;
  border: 3px solid var(--border);
  border-radius: 4px;
  background: var(--accent);
  color: var(--bg);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s, box-shadow 0.05s;
  box-shadow: 0 4px 0 var(--border);
  min-height: 56px;
  user-select: none;
}

.answer-btn:hover:not(:disabled),
.control-btn:hover:not(:disabled) {
  background: var(--accent-hover);
}

.answer-btn:active:not(:disabled),
.control-btn:active:not(:disabled) {
  background: var(--accent-pressed);
  transform: translateY(2px);
  box-shadow: 0 2px 0 var(--border);
}

.answer-btn:focus-visible,
.control-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.answer-btn:disabled,
.control-btn:disabled {
  background: var(--disabled);
  color: var(--text);
  cursor: not-allowed;
  opacity: 0.7;
  box-shadow: 0 4px 0 var(--border);
  transform: none;
}

.controls {
  display: flex;
  gap: 1rem;
}

.control-btn {
  flex: 1;
  font-size: 1.125rem;
  padding: 0.75rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  .question {
    font-size: 1.5rem;
  }
  .answer-btn {
    font-size: 1.125rem;
    padding: 0.875rem;
  }
  .controls {
    flex-direction: column;
  }
}

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let currentIndex = 0;
let score = 0;
let answered = false;

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function renderQuestion() {
  const q = questions[currentIndex];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.setAttribute('aria-label', `Answer A: ${q.a}`);
  answerB.setAttribute('aria-label', `Answer B: ${q.b}`);
  answerA.disabled = false;
  answerB.disabled = false;
  answered = false;
  nextBtn.disabled = true;
}

function handleAnswer(choice) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
  if (choice === questions[currentIndex].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

function handleNext() {
  if (currentIndex < questions.length - 1) {
    currentIndex += 1;
    renderQuestion();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
}

function handleRestart() {
  currentIndex = 0;
  score = 0;
  scoreEl.textContent = '0';
  renderQuestion();
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));
nextBtn.addEventListener('click', handleNext);
restartBtn.addEventListener('click', handleRestart);

renderQuestion();
